parameters.jsCode:
const linux = $('GitHub — Stats jarvis-linux').first().json;
const turbo = $('GitHub — Stats turbo (principal)').first().json;
const commits = $('GitHub — Derniers Commits').first().json;

const now = new Date().toLocaleDateString('fr-FR', { weekday: 'long', day: 'numeric', month: 'long' });

// Stats jarvis-linux
const linuxStars = linux?.stargazers_count ?? 0;
const linuxForks = linux?.forks_count ?? 0;
const linuxWatchers = linux?.watchers_count ?? 0;
const linuxIssues = linux?.open_issues_count ?? 0;
const linuxUpdated = linux?.updated_at ? new Date(linux.updated_at).toLocaleString('fr-FR') : 'N/A';

// Stats turbo
const turboStars = turbo?.stargazers_count ?? 0;
const turboForks = turbo?.forks_count ?? 0;

// Derniers commits
let commitLines = 'N/A';
if (Array.isArray(commits) && commits.length > 0) {
  commitLines = commits.map(c => {
    const msg = c.commit?.message?.split('\n')[0]?.substring(0, 60) || 'commit';
    const date = c.commit?.author?.date ? new Date(c.commit.author.date).toLocaleDateString('fr-FR') : '';
    return `  • ${date}: ${msg}`;
  }).join('\n');
}

const message = `⭐ *JARVIS GitHub Tracker — ${now}*\n\n📦 *jarvis-linux:*\n  ⭐ Stars: ${linuxStars} | 🍴 Forks: ${linuxForks}\n  👁️ Watchers: ${linuxWatchers} | 🐛 Issues: ${linuxIssues}\n  🕐 Mis à jour: ${linuxUpdated}\n\n📦 *turbo (principal):*\n  ⭐ Stars: ${turboStars} | 🍴 Forks: ${turboForks}\n\n📝 *Derniers commits (jarvis-linux):*\n${commitLines}\n\n━━━━━━━━━━━━━━━━\n_Tracking quotidien JARVIS v12.6_`;

return [{ json: { message, linuxStars, turboStars, linuxUpdated } }];

